// ---- lib/frontmatter.js ----
/**
 * Minimal YAML-frontmatter reader/writer.
 *
 * Deliberately dependency-free: this same code is inlined into n8n Code nodes,
 * which cannot `npm install`. It supports the subset of YAML the Obsidian
 * templates in ../templates use:
 *
 *   key: value          scalars (string / number / boolean / empty)
 *   key: "value"        quoted strings (single or double)
 *   key:                empty value -> null
 *   key:                block lists
 *     - one
 *     - two
 *   key: [one, two]     inline lists
 *
 * Anything fancier (nested maps, multi-line scalars, anchors) is out of scope
 * and will be read back as a plain string. Keep the templates simple.
 */

const FRONTMATTER_RE = /^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)/;

function parseScalar(raw) {
  const value = raw.trim();
  if (value === '') return null;

  const quoted = value.match(/^"(.*)"$/s) || value.match(/^'(.*)'$/s);
  if (quoted) return quoted[1];

  if (value === 'true') return true;
  if (value === 'false') return false;
  if (value === 'null' || value === '~') return null;

  // Inline list: [a, b, c]
  if (value.startsWith('[') && value.endsWith(']')) {
    const inner = value.slice(1, -1).trim();
    if (inner === '') return [];
    return inner.split(',').map((part) => parseScalar(part));
  }

  if (/^-?\d+$/.test(value)) return Number.parseInt(value, 10);
  if (/^-?\d*\.\d+$/.test(value)) return Number.parseFloat(value);

  return value;
}

/**
 * Split a note into its frontmatter object and its body.
 * A note without frontmatter yields `{ data: {}, body: <whole note> }`.
 */
function parseNote(content) {
  const text = String(content ?? '');
  const match = text.match(FRONTMATTER_RE);
  if (!match) return { data: {}, body: text, raw: null };

  const data = {};
  const lines = match[1].split(/\r?\n/);

  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i];
    if (line.trim() === '' || line.trimStart().startsWith('#')) continue;

    const keyMatch = line.match(/^([A-Za-z0-9_-]+)\s*:(.*)$/);
    if (!keyMatch) continue;

    const key = keyMatch[1];
    const inline = keyMatch[2];

    if (inline.trim() === '') {
      // Could be an empty value or the head of a block list.
      const items = [];
      let j = i + 1;
      while (j < lines.length && /^\s*-\s+/.test(lines[j])) {
        items.push(parseScalar(lines[j].replace(/^\s*-\s+/, '')));
        j += 1;
      }
      if (items.length > 0) {
        data[key] = items;
        i = j - 1;
      } else {
        data[key] = null;
      }
      continue;
    }

    data[key] = parseScalar(inline);
  }

  return { data, body: text.slice(match[0].length), raw: match[1] };
}

function serializeValue(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'boolean' || typeof value === 'number') return String(value);
  const str = String(value);
  // Quote anything that would otherwise change meaning on re-parse.
  if (str === '' || /^[\s]|[\s]$|^[[{>|*&!%@`-]|:\s|#/.test(str)) {
    return `"${str.replace(/"/g, '\\"')}"`;
  }
  return str;
}

/**
 * Rewrite a note's frontmatter with `updates`, preserving key order and the
 * body byte-for-byte. Used to stamp `orbit_card_id` back into the vault after
 * a card is created — the step that makes the sync idempotent.
 */
function updateFrontmatter(content, updates) {
  const text = String(content ?? '');
  const match = text.match(FRONTMATTER_RE);
  const pending = { ...updates };

  if (!match) {
    const block = Object.entries(pending)
      .map(([key, value]) => `${key}: ${serializeValue(value)}`)
      .join('\n');
    return `---\n${block}\n---\n${text}`;
  }

  const lines = match[1].split(/\r?\n/);
  const out = lines.map((line) => {
    const keyMatch = line.match(/^([A-Za-z0-9_-]+)\s*:(.*)$/);
    if (!keyMatch) return line;
    const key = keyMatch[1];
    if (!Object.prototype.hasOwnProperty.call(pending, key)) return line;
    const value = pending[key];
    delete pending[key];
    return `${key}: ${serializeValue(value)}`;
  });

  for (const [key, value] of Object.entries(pending)) {
    out.push(`${key}: ${serializeValue(value)}`);
  }

  return `---\n${out.join('\n')}\n---\n${text.slice(match[0].length)}`;
}

// ---- lib/normalize-markdown.js ----
/**
 * Turn Obsidian-flavoured markdown into something a non-Obsidian system can
 * render. Wikilinks, embeds, callouts, highlights, comments, block refs and
 * Dataview blocks all mean nothing outside the vault; left alone they show up
 * on the board as literal punctuation.
 *
 * Fenced and inline code are masked before any other rule runs, so a code
 * sample containing [[foo]] or #tag survives verbatim.
 *
 * Output format is chosen by the caller because Orbit's description field
 * format is not yet confirmed — see README "Confirm the API contract".
 */

// Sentinel is plain ASCII and improbable in prose, so masking never collides
// with note content and stays greppable when debugging a bad render.
const MASK_PREFIX = '@@ORBITCODE';
const MASK_SUFFIX = '@@';
const MASK_RE = /@@ORBITCODE(\d+)@@/g;

function maskCode(text) {
  const blocks = [];
  const stash = (match) => {
    blocks.push(match);
    return `${MASK_PREFIX}${blocks.length - 1}${MASK_SUFFIX}`;
  };
  const masked = text
    .replace(/```[\s\S]*?```/g, stash)
    .replace(/`[^`\n]+`/g, stash);
  return { masked, blocks };
}

function unmaskCode(text, blocks) {
  return text.replace(MASK_RE, (_, index) => blocks[Number(index)]);
}

function obsidianUri(vault, target) {
  return `obsidian://open?vault=${encodeURIComponent(vault)}&file=${encodeURIComponent(target)}`;
}

/**
 * @param {string} body        note body, frontmatter already removed
 * @param {object} [options]
 * @param {'text'|'uri'} [options.wikilinks='text']  render [[links]] as plain
 *        text, or as obsidian:// links (only useful if every board reader has
 *        the vault — usually they do not)
 * @param {string} [options.vault]  vault name, required when wikilinks='uri'
 * @param {boolean} [options.stripTags=true]  pull #tags out of the prose and
 *        return them separately, for mapping onto Orbit labels
 * @returns {{ markdown: string, tags: string[], warnings: string[] }}
 */
function normalizeMarkdown(body, options = {}) {
  const { wikilinks = 'text', vault, stripTags = true } = options;
  const warnings = [];
  const tags = [];

  let text = String(body ?? '').replace(/\r\n/g, '\n');
  const { masked, blocks } = maskCode(text);
  text = masked;

  // Dataview/query fences are already masked; blank them by inspecting the
  // captured blocks, so unmasking drops them entirely.
  blocks.forEach((block, index) => {
    if (/^```\s*(dataview|dataviewjs|query|tasks)\b/i.test(block)) {
      blocks[index] = '';
      warnings.push('Removed a Dataview/query block — it cannot render outside Obsidian.');
    }
  });

  // %% Obsidian comments %% never leave the vault.
  text = text.replace(/%%[\s\S]*?%%/g, '');

  // ![[embed]] — attachments and transclusions do not travel.
  text = text.replace(/!\[\[([^\]]+)\]\]/g, (_, target) => {
    warnings.push(`Dropped embed "${target}" — attachments are not synced.`);
    return '';
  });

  // [[Note|Alias]] and [[Note]]
  text = text.replace(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g, (_, target, alias) => {
    const label = (alias || target).trim();
    if (wikilinks === 'uri') {
      if (!vault) {
        warnings.push('wikilinks="uri" needs a vault name; fell back to plain text.');
        return label;
      }
      return `[${label}](${obsidianUri(vault, target.trim())})`;
    }
    return label;
  });

  // > [!note] Title / > body  ->  **Title** / body
  text = text.replace(
    // [ \t]* rather than \s*: \s would swallow the newline and eat the body.
    /^>[ \t]*\[!(\w+)\][+-]?[ \t]*(.*)$((?:\n>.*)*)/gm,
    (_, kind, title, rest) => {
      const heading = (title || '').trim() || kind.toUpperCase();
      const bodyLines = rest
        .split('\n')
        .filter((line) => line.trim() !== '')
        .map((line) => line.replace(/^>\s?/, ''));
      return [`**${heading}**`, ...bodyLines].join('\n');
    },
  );

  // ==highlight== has no portable equivalent; bold is the closest.
  text = text.replace(/==([^=\n]+)==/g, '**$1**');

  // Trailing ^block-ids.
  text = text.replace(/[ \t]*\^[A-Za-z0-9-]+[ \t]*$/gm, '');

  // Footnote refs and definitions.
  let sawFootnote = false;
  text = text.replace(/^\[\^[^\]]+\]:.*$/gm, () => {
    sawFootnote = true;
    return '';
  });
  text = text.replace(/\[\^[^\]]+\]/g, () => {
    sawFootnote = true;
    return '';
  });
  if (sawFootnote) warnings.push('Removed footnotes — no footnote support on the card.');

  if (stripTags) {
    // A tag is #word preceded by start-of-line or whitespace. Headings are
    // "# " (hash then space) so they never match.
    text = text.replace(/(^|[\s(])#([A-Za-z][\w/-]*)/gm, (match, lead, tag) => {
      tags.push(tag);
      return lead;
    });
  }

  text = unmaskCode(text, blocks);

  // Tidy the blank lines the removals left behind.
  text = text
    .split('\n')
    .map((line) => line.replace(/[ \t]+$/, ''))
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  return { markdown: text, tags: [...new Set(tags)], warnings };
}

/** Strip markdown syntax down to readable plain text. */
function toPlainText(markdown) {
  return String(markdown)
    .replace(/```[\s\S]*?```/g, (block) => block.replace(/```\w*\n?/g, '').trimEnd())
    .replace(/`([^`\n]+)`/g, '$1')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^\s*>\s?/gm, '')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/(^|[^*])\*([^*\n]+)\*/g, '$1$2')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/^\s*[-*+]\s+/gm, '- ')
    .replace(/^---+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function inlineHtml(text) {
  return escapeHtml(text)
    .replace(/`([^`\n]+)`/g, (_, code) => `<code>${code}</code>`)
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>')
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2">$1</a>');
}

/**
 * A deliberately small markdown -> HTML renderer: headings, paragraphs, lists,
 * blockquotes, fenced code, rules, and the inline set above. It is not a
 * CommonMark implementation — no tables, no nested lists. If Orbit accepts
 * HTML and you outgrow this, swap in `marked` on a self-hosted n8n with
 * NODE_FUNCTION_ALLOW_EXTERNAL set (see README).
 */
function toHtml(markdown) {
  const lines = String(markdown).split('\n');
  const out = [];
  let paragraph = [];
  let list = null; // 'ul' | 'ol'
  let quote = [];
  let fence = null;

  const flushParagraph = () => {
    if (paragraph.length) {
      out.push(`<p>${inlineHtml(paragraph.join(' '))}</p>`);
      paragraph = [];
    }
  };
  const flushList = () => {
    if (list) {
      out.push(`</${list}>`);
      list = null;
    }
  };
  const flushQuote = () => {
    if (quote.length) {
      out.push(`<blockquote>${inlineHtml(quote.join(' '))}</blockquote>`);
      quote = [];
    }
  };
  const flushAll = () => {
    flushParagraph();
    flushList();
    flushQuote();
  };

  for (const line of lines) {
    const fenceMatch = line.match(/^```(\w*)\s*$/);
    if (fenceMatch) {
      if (fence === null) {
        flushAll();
        fence = [];
      } else {
        out.push(`<pre><code>${escapeHtml(fence.join('\n'))}</code></pre>`);
        fence = null;
      }
      continue;
    }
    if (fence !== null) {
      fence.push(line);
      continue;
    }

    if (line.trim() === '') {
      flushAll();
      continue;
    }

    const heading = line.match(/^(#{1,6})\s+(.*)$/);
    if (heading) {
      flushAll();
      const level = heading[1].length;
      out.push(`<h${level}>${inlineHtml(heading[2])}</h${level}>`);
      continue;
    }

    if (/^\s*(---+|\*\*\*+)\s*$/.test(line)) {
      flushAll();
      out.push('<hr>');
      continue;
    }

    const bullet = line.match(/^\s*[-*+]\s+(.*)$/);
    const ordered = line.match(/^\s*\d+\.\s+(.*)$/);
    if (bullet || ordered) {
      flushParagraph();
      flushQuote();
      const wanted = bullet ? 'ul' : 'ol';
      if (list !== wanted) {
        flushList();
        out.push(`<${wanted}>`);
        list = wanted;
      }
      out.push(`<li>${inlineHtml((bullet || ordered)[1])}</li>`);
      continue;
    }
    flushList();

    const quoted = line.match(/^\s*>\s?(.*)$/);
    if (quoted) {
      flushParagraph();
      quote.push(quoted[1]);
      continue;
    }
    flushQuote();

    paragraph.push(line.trim());
  }

  if (fence !== null) out.push(`<pre><code>${escapeHtml(fence.join('\n'))}</code></pre>`);
  flushAll();
  return out.join('\n');
}

/** Render normalized markdown into whichever format Orbit accepts. */
function render(markdown, format) {
  switch (format) {
    case 'html':
      return toHtml(markdown);
    case 'text':
      return toPlainText(markdown);
    case 'markdown':
    default:
      return markdown;
  }
}

// ---- lib/build-payload.js ----
/**
 * Turn an Obsidian note into an Orbit API payload.
 *
 * Three jobs, in order:
 *   1. validate against the card-type rules (the People Ops SOPs, encoded)
 *   2. render the body into whatever format Orbit's description field takes
 *   3. map frontmatter keys onto Orbit field names via config.field_map
 *
 * Validation runs first and hard-fails: a card that reaches the board missing
 * a US salary range or a start date costs more to fix in public than to catch
 * here.
 */

/** Non-cryptographic, dependency-free FNV-1a. Only used for change detection. */
function hashString(value) {
  let hash = 0x811c9dc5;
  const str = String(value);
  for (let i = 0; i < str.length; i += 1) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

/** Stable stringify so key order never changes the hash. */
function stableStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value) ?? 'null';
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(',')}]`;
  const keys = Object.keys(value).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify(value[k])}`).join(',')}}`;
}

function setPath(target, path, value) {
  const parts = String(path).split('.');
  let node = target;
  for (let i = 0; i < parts.length - 1; i += 1) {
    if (typeof node[parts[i]] !== 'object' || node[parts[i]] === null) node[parts[i]] = {};
    node = node[parts[i]];
  }
  node[parts[parts.length - 1]] = value;
}

function isBlank(value) {
  return value === null || value === undefined || String(value).trim() === '';
}

/**
 * Card-type rules drawn from the People Ops SOPs. `requires` is unconditional;
 * `conditional` entries fire when their `when` predicate matches.
 */
const CARD_RULES = {
  new_role: {
    requires: ['title', 'department', 'hiring_manager', 'headcount'],
    conditional: [
      {
        when: (fm) => /\b(us|usa|united states|remote us)\b/i.test(String(fm.location ?? '')),
        requires: ['salary_range'],
        because: 'US-based roles must publish a salary range before posting.',
      },
    ],
  },
  offer_approval: {
    // The Head of Department raises this card, but only after salary
    // expectations and start date have been confirmed with the candidate.
    requires: ['candidate', 'role', 'salary_expectation', 'start_date', 'head_of_department'],
  },
  exit: {
    requires: ['employee', 'last_day', 'reason', 'manager'],
  },
  salary_increase: {
    // Finance wants the benchmark reasoning on the card itself.
    requires: ['employee', 'current_salary', 'proposed_salary', 'benchmark_rationale'],
  },
};

/**
 * Guard against a stale note dragging a card backwards through the approval
 * flow. Obsidian may only place cards in columns it owns; everything past
 * HR Review belongs to Finance, Rory and the board itself.
 */
function resolveColumn(frontmatter, config, currentColumn) {
  const order = config.column_order ?? [];
  const owned = config.owned_columns ?? [];
  const desired = frontmatter.orbit_column;
  const warnings = [];

  if (isBlank(desired)) return { column: null, warnings };

  if (!order.includes(desired)) {
    warnings.push(`Unknown column "${desired}" — not in config.column_order. Leaving it alone.`);
    return { column: null, warnings };
  }

  if (!owned.includes(desired)) {
    warnings.push(
      `Column "${desired}" is not owned by the vault (owned: ${owned.join(', ') || 'none'}). ` +
        'Orbit stays the system of record for approvals; not moving the card.',
    );
    return { column: null, warnings };
  }

  if (currentColumn && order.includes(currentColumn)) {
    if (order.indexOf(desired) < order.indexOf(currentColumn)) {
      warnings.push(
        `Refusing to move "${currentColumn}" back to "${desired}" — the sync never rewinds ` +
          'the approval flow. Move it in Orbit if that is really what you want.',
      );
      return { column: null, warnings };
    }
    if (desired === currentColumn) return { column: null, warnings };
  }

  return { column: desired, warnings };
}

function validate(cardType, frontmatter) {
  const rules = CARD_RULES[cardType];
  if (!rules) {
    return [`Unknown orbit_type "${cardType}". Known types: ${Object.keys(CARD_RULES).join(', ')}.`];
  }

  const errors = [];
  for (const field of rules.requires) {
    if (isBlank(frontmatter[field])) errors.push(`Missing required field "${field}".`);
  }
  for (const rule of rules.conditional ?? []) {
    if (!rule.when(frontmatter)) continue;
    for (const field of rule.requires) {
      if (isBlank(frontmatter[field])) errors.push(`Missing "${field}" — ${rule.because}`);
    }
  }
  return errors;
}

/**
 * @param {object} input
 * @param {string} input.path     vault-relative note path, used in messages
 * @param {string} input.content  raw note, frontmatter included
 * @param {object} input.config   see config.example.json
 * @param {string} [input.currentColumn]  card's column in Orbit right now,
 *        fetched on the update path; omit when creating
 * @returns {{ ok: boolean, skipped?: string, errors: string[], warnings: string[],
 *             action: 'create'|'update'|null, cardId: string|null,
 *             payload: object|null, hash: string|null, tags: string[] }}
 */
function buildPayload({ path, content, config, currentColumn }) {
  const { data: fm, body } = parseNote(content);
  const result = {
    ok: false,
    errors: [],
    warnings: [],
    action: null,
    cardId: null,
    payload: null,
    hash: null,
    tags: [],
    path,
  };

  if (fm.sync !== true) {
    result.skipped = 'sync is not true';
    return result;
  }

  const cardType = fm.orbit_type;
  result.errors.push(...validate(cardType, fm));

  const normalized = normalizeMarkdown(body, {
    wikilinks: config.wikilinks ?? 'text',
    vault: config.vault,
    stripTags: config.strip_tags !== false,
  });
  result.warnings.push(...normalized.warnings);
  result.tags = normalized.tags;

  if (result.errors.length > 0) return result;

  const payload = {};

  for (const [key, value] of Object.entries(config.constant_fields ?? {})) {
    setPath(payload, key, value);
  }

  const map = config.field_map ?? {};
  for (const [noteKey, orbitPath] of Object.entries(map)) {
    if (isBlank(fm[noteKey])) continue;
    setPath(payload, orbitPath, fm[noteKey]);
  }

  if (config.description_field) {
    setPath(payload, config.description_field, render(normalized.markdown, config.description_format));
  }

  if (config.board_field && config.board_id) {
    setPath(payload, config.board_field, config.board_id);
  }

  if (config.tags_field && result.tags.length > 0) {
    setPath(payload, config.tags_field, result.tags);
  }

  const column = resolveColumn(fm, config, currentColumn);
  result.warnings.push(...column.warnings);
  if (column.column && config.column_field) {
    const mapped = (config.column_map ?? {})[column.column] ?? column.column;
    setPath(payload, config.column_field, mapped);
  }

  result.cardId = isBlank(fm.orbit_card_id) ? null : String(fm.orbit_card_id);
  result.action = result.cardId ? 'update' : 'create';
  result.payload = payload;
